=You are the syllabus co-creation analyst. Analyze the transcript between the Cognitive Interviewer agent and the user.

Read the baseline Syllabus JSON:
{{ JSON.stringify($json.baseline_syllabus) }}

And the session transcript:
{{ $json.transcript ?? $json.body?.transcript }}

Identify all structural updates proposed, agreed upon, or corrected. Output strictly ONE valid JSON matching the target schema. Use status tags: 'existing', 'added', 'removed', 'modified'.

parameters.jsCode:
let rawContent = $json.message?.content || $json.output || $json.text || '';
if (typeof rawContent === 'object') {
  rawContent = JSON.stringify(rawContent);
}

rawContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

let candidate;
let errors = [];

try {
  candidate = JSON.parse(rawContent);
} catch (e) {
  errors.push('JSON Parsing failed: ' + e.message);
}

if (candidate) {
  const REQUIRED_KEYS = ['syllabus_id', 'version', 'nodes', 'connections', 'change_log', 'open_gaps'];
  REQUIRED_KEYS.forEach(k => {
    if (!(k in candidate)) errors.push(`Missing top-level key: ${k}`);
  });

  if (Array.isArray(candidate.nodes)) {
    candidate.nodes.forEach((n, idx) => {
      if (!n.id) errors.push(`Node at index ${idx} is missing an id`);
      if (!['existing', 'added', 'removed', 'modified'].includes(n.status)) {
        errors.push(`Node ${n.id || idx} has invalid status: ${n.status}`);
      }
    });
  } else {
    errors.push('nodes field must be an array');
  }
}

return {
  json: {
    ...$json,
    updated_syllabus: candidate || null,
    _validation: {
      isValid: errors.length === 0,
      errors: errors
    }
  }
};

// Graph Consistency Validator
// Checks for: circular references, orphan nodes, invalid prerequisite links

const syllabus = $json.updated_syllabus || $json;
const errors = [];
const warnings = [];

if (!syllabus.nodes || !Array.isArray(syllabus.nodes)) {
  errors.push('nodes field is required and must be an array');
  return { json: { ...$json, graph_consistency: { isValid: false, errors, warnings } } };
}

if (!syllabus.connections || !Array.isArray(syllabus.connections)) {
  errors.push('connections field is required and must be an array');
  return { json: { ...$json, graph_consistency: { isValid: false, errors, warnings } } };
}

const nodeIds = new Set(syllabus.nodes.map(n => n.id));

// Check 1: Verify all connection references point to existing nodes
syllabus.connections.forEach((conn, idx) => {
  if (!nodeIds.has(conn.from)) {
    errors.push(`Connection[${idx}]: Reference to non-existent node: '${conn.from}' (from field)`);
  }
  if (!nodeIds.has(conn.to)) {
    errors.push(`Connection[${idx}]: Reference to non-existent node: '${conn.to}' (to field)`);
  }
});

// Check 2: Detect circular dependencies (simple cycle detection)
const adjacencyList = new Map();
syllabus.connections.forEach(conn => {
  if (!adjacencyList.has(conn.from)) {
    adjacencyList.set(conn.from, []);
  }
  adjacencyList.get(conn.from).push(conn.to);
});

const visited = new Set();
const recursionStack = new Set();
let hasCircularRef = false;

function detectCycle(nodeId) {
  visited.add(nodeId);
  recursionStack.add(nodeId);

  const neighbors = adjacencyList.get(nodeId) || [];
  for (const neighbor of neighbors) {
    if (!visited.has(neighbor)) {
      if (detectCycle(neighbor)) {
        hasCircularRef = true;
        return true;
      }
    } else if (recursionStack.has(neighbor)) {
      hasCircularRef = true;
      return true;
    }
  }

  recursionStack.delete(nodeId);
  return false;
}

for (const nodeId of nodeIds) {
  if (!visited.has(nodeId)) {
    detectCycle(nodeId);
  }
}

if (hasCircularRef) {
  errors.push('Graph contains circular dependencies in connections');
}

// Check 3: Detect orphan nodes (nodes with no connections)
const connectedNodes = new Set();
syllabus.connections.forEach(conn => {
  connectedNodes.add(conn.from);
  connectedNodes.add(conn.to);
});

const orphanNodes = [...nodeIds].filter(id => !connectedNodes.has(id));
if (orphanNodes.length > 0) {
  warnings.push(`Orphan nodes detected (no connections): ${orphanNodes.join(', ')}`);
}

return {
  json: {
    ...$json,
    graph_consistency: {
      isValid: errors.length === 0,
      errors,
      warnings,
      nodeCount: nodeIds.size,
      connectionCount: syllabus.connections.length,
      orphanNodes
    }
  }
};

const updatedSyllabus = $json.updated_syllabus;
return {
  json: {
    status: 'success',
    message: 'Syllabus updated and stored successfully.',
    syllabus_id: updatedSyllabus.syllabus_id,
    version: updatedSyllabus.version + 1,
    nodesCount: updatedSyllabus.nodes.length,
    connectionsCount: updatedSyllabus.connections.length,
    persistedAt: new Date().toISOString(),
    data: updatedSyllabus
  }
};

const graphConsistency = $json.graph_consistency;
return {
  json: {
    status: 'error',
    error_type: 'GRAPH_CONSISTENCY_FAILED',
    details: {
      errors: graphConsistency.errors,
      warnings: graphConsistency.warnings,
      nodeCount: graphConsistency.nodeCount,
      connectionCount: graphConsistency.connectionCount,
      orphanNodes: graphConsistency.orphanNodes
    },
    timestamp: new Date().toISOString()
  }
};

const validation = $json._validation;
return {
  json: {
    status: 'error',
    error_type: 'SCHEMA_VALIDATION_FAILED',
    details: validation.errors,
    timestamp: new Date().toISOString()
  }
};
